text:
.menulist,
.input-field {
  & ~ .input-error-message {
    color: light-dark(var(--color-critical-default), var(--color-critical-pressed));
    display: none;
    position: absolute;
    inset-block-end: calc(-1 * var(--hub-form-input-line-height) - var(--space-step));
    white-space: nowrap;
    text-overflow: ellipsis;
    overflow: hidden;
    inline-size: -moz-available;
    font-size: var(--hub-input-error-message-font-size);

    &.security-warning {
      white-space: normal;
      position: relative;
      font-size: 1rem;
      inset-block-end: 0;
      margin-block: 2px -15px;

      & .more-info-link {
        color: light-dark(var(--color-critical-default), var(--color-critical-pressed));
        text-decoration: underline;
      }
    }

    & span {
      font-weight: 600;
    }
  }

  &:user-invalid,
  &[aria-invalid="true"],
  &.warning {
    border-color: light-dark(var(--color-critical-default), var(--color-critical-pressed));
    outline: 1px solid light-dark(var(--color-critical-default), var(--color-critical-pressed));
    outline-offset: 0;

    &:focus {
      border-color: light-dark(var(--color-critical-default), var(--color-critical-pressed));
    }

    & ~ label {
      color: light-dark(var(--color-critical-default), var(--color-critical-pressed));
    }

    & ~ .input-error-message {
      display: inline;
    }
  }
}
